def solve(inp,bg,verbose=False):
    H,W=len(inp),len(inp[0])
    out=[r[:] for r in inp]
    P={(i,j) for i in range(H) for j in range(W) if inp[i][j]==8}
    # hyp A: cell becomes 2 if strictly between two 8s in its row or col (both directions see 8)
    for i in range(H):
        for j in range(W):
            if inp[i][j]!=bg: continue
            if (any(P[a][j] for a in range(i)) and any(P[a][j] for a in range(i+1,H))) or \
               (any(P[i][b] for b in range(j)) and any(P[i][b] for b in range(j+1,W))):
                out[i][j]=2
    if verbose:
        return out
    return out
