    seen=set(st)
    while st:
        r,c=st.pop()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and g[nr][nc]==0 and (nr,nc) not in seen:
                seen.add((nr,nc)); st.append((nr,nc))
    for r in range(H):
        for c in range(W):
            if g[r][c]==0 and (r,c) not in seen: out[r][c]=2
    return out
